      "multiEdit" -> MultiEdit(json.decodeFromJsonElement(element))
      "edit" -> Edit(json.decodeFromJsonElement(element))
      else -> Unknown(element)
    }

    override fun encode(json: Json, value: ForkReplayOp): JsonElement = when (value) {
      is Write -> json.encodeToJsonElement(value.value)
      is MultiEdit -> json.encodeToJsonElement(value.value)
      is Edit -> json.encodeToJsonElement(value.value)
      is Unknown -> value.value
    }
  }
}

