      "revoke" -> Revoke(json.decodeFromJsonElement(element))
      "rotate" -> Rotate(json.decodeFromJsonElement(element))
      "rename" -> Rename(json.decodeFromJsonElement(element))
      else -> Unknown(element)
    }

    override fun encode(json: Json, value: LogBody): JsonElement = when (value) {
      is Genesis -> json.encodeToJsonElement(value.value)
      is AddDevice -> json.encodeToJsonElement(value.value)
      is AddHost -> json.encodeToJsonElement(value.value)
