  data class Text(val value: RemoteToolCallChildText) : RemoteToolCallChild
  data class ToolUse(val value: RemoteToolCallChildToolUse) : RemoteToolCallChild
  data class Unknown(val value: JsonElement) : RemoteToolCallChild

  object Serializer : TaggedUnionSerializer<RemoteToolCallChild>("RemoteToolCallChild", "kind") {
    override fun decode(json: Json, tag: String?, element: JsonElement): RemoteToolCallChild = when (tag) {
      "text" -> Text(json.decodeFromJsonElement(element))
      "tool_use" -> ToolUse(json.decodeFromJsonElement(element))
      else -> Unknown(element)
    }

    override fun encode(json: Json, value: RemoteToolCallChild): JsonElement = when (value) {
      is Text -> json.encodeToJsonElement(value.value)
      is ToolUse -> json.encodeToJsonElement(value.value)
      is Unknown -> value.value
    }
  }
}

